/*
 * PipelineStepper — live FDIR run feedback.
 *
 * The backend streams SSE STATUS/OBSERVATION events whose `data` is a plain
 * string tagged with the pipeline stage in brackets, e.g.
 *   "[DETECTION] Analyzing pre-fault telemetry..."
 *   "[PHYSICS_VALIDATION] ..."
 * We scan the accumulated event stream for those tags to drive an accurate
 * stepper — no client-side simulation, only what the stream actually reported.
 *
 * Stage vocabulary and order are derived from the tags emitted in
 * app/agent/agent.py; RESULT is the terminal "Diagnosis" step.
 */

import React from "react";
import Icon from "./Icon";

// Operator-facing pipeline, in run order. Each step lists the backend tag(s)
// whose appearance in the stream marks it reached. ESA taxonomy mapping is
// folded into the knowledge-retrieval step it belongs to.
const STAGES = [
  { key: "ingest", label: "Ingest", tags: ["INGESTION"] },
  { key: "detect", label: "Detect", tags: ["DETECTION"] },
  { key: "estimate", label: "State Est.", tags: ["STATE_ESTIMATION"] },
  { key: "retrieve", label: "Retrieve", tags: ["RAG_RETRIEVAL", "ESA_MAPPING"] },
  { key: "hypotheses", label: "Hypotheses", tags: ["HYPOTHESIS_GENERATION"] },
  { key: "reason", label: "LLM Ranking", tags: ["LLM_RANKING"] },
  { key: "physics", label: "Physics", tags: ["PHYSICS_VALIDATION"] },
  { key: "safety", label: "Safety", tags: ["SAFETY_VALIDATION"] },
  { key: "diagnosis", label: "Diagnosis", tags: ["FINAL_RESULT"] },
];

function highestReachedIndex(events) {
  let reached = -1;
  for (const ev of events || []) {
    const text = String(ev?.data ?? "").toUpperCase();
    if (ev?.type === "result") reached = Math.max(reached, STAGES.length - 1);
    for (let i = 0; i < STAGES.length; i += 1) {
      if (STAGES[i].tags.some((t) => text.includes(`[${t}]`) || text.includes(t))) {
        reached = Math.max(reached, i);
      }
    }
  }
  return reached;
}

export default function PipelineStepper({ analysis, children }) {
  const status = analysis?.status || "IDLE";
  const events = analysis?.events || [];
  const hasOutput = Boolean(analysis?.output);
  const isRunning = status === "RUNNING";
  const isError = status === "ERROR";
  const isComplete = status === "COMPLETE" || hasOutput;

  const reached = highestReachedIndex(events);
  const activeIndex = reached >= 0 ? reached : 0;

  const stateFor = (i) => {
    if (isComplete) return "done";
    if (isError) {
      if (i < activeIndex) return "done";
      if (i === activeIndex) return "failed";
      return "idle";
    }
    if (isRunning) {
      if (i < activeIndex) return "done";
      if (i === activeIndex) return "active";
      return "idle";
    }
    return "idle";
  };

  const doneCount = isComplete
    ? STAGES.length
    : STAGES.reduce((n, _s, i) => (stateFor(i) === "done" ? n + 1 : n), 0);

  const pulseClass = isError
    ? "pipeline__pulse--crit"
    : isComplete
    ? "pipeline__pulse--ok"
    : isRunning
    ? "pipeline__pulse--live"
    : "";

  const statusLabel = isError
    ? "RUN FAILED"
    : isComplete
    ? "ANALYSIS COMPLETE"
    : isRunning
    ? "ANALYSIS RUNNING"
    : "STANDING BY";

  return (
    <section className="pipeline" aria-label="FDIR pipeline progress">
      <div className="pipeline__bar">
        <h2 className="pipeline__title">
          <span className={`pipeline__pulse ${pulseClass}`} aria-hidden="true" />
          FDIR Pipeline · {statusLabel}
        </h2>
        <span className="pipeline__count">
          {doneCount}/{STAGES.length} stages
        </span>
      </div>
      <ol className="pipeline__track">
        {STAGES.map((stage, i) => {
          const st = stateFor(i);
          return (
            <li key={stage.key} className={`pstep pstep--${st}`}>
              <span className="pstep__node">
                {st === "done" ? (
                  <Icon name="check" size={13} />
                ) : st === "failed" ? (
                  <Icon name="cross" size={13} />
                ) : (
                  i + 1
                )}
              </span>
              <span className="pstep__label">{stage.label}</span>
            </li>
          );
        })}
      </ol>
      {children}
    </section>
  );
}
