/*
 * Observation Reconciliation / Separation View (ReconciliationView.jsx)
 *
 * Phase 24/26 — Deterministic multi-channel observation reconciliation.
 *
 * Core Principle: CORRELATION != IDENTITY.
 *
 * This view is a dumb renderer of the backend result served by
 * POST /api/v1/reconciliation (fetched per-scenario in SentinelContext and
 * exposed as the `reconciliation` entity). It NEVER fetches, derives, or
 * invents reconciliation state, and it never re-implements the engine: every
 * count and relationship shown here is computed by the deterministic Phase 24
 * engine on the backend.
 *
 * The endpoint distinguishes states explicitly so the UI never has to convert
 * missing data into a misleading zero:
 *   A  disabled          reconciliation_enabled === false (flag off)
 *   B  not run           no scenario selected yet / no data
 *   C  no relationships  executed, 0-or-1 case, no cross-case link
 *   D  cases             executed, multiple cases with relationships
 *   E  conflict          executed, at least one CONFLICT relationship
 *   F  backend error     the fetch failed
 */

import React from "react";
import { useSentinel } from "../../state/SentinelContext";
import Panel from "../ui/Panel";
import StatusBadge from "../ui/StatusBadge";
import DataTable from "../ui/DataTable";

const REL_HELP = Object.freeze({
  DUPLICATE: "The same observation recorded twice — merge permitted.",
  SAME_CASE: "Different observations of one underlying fault — merge permitted.",
  RELATED:
    "Different faults with a deterministic relationship (possible propagation). Merge NOT permitted; physics validation pending.",
  SEPARATE: "No relationship the deterministic signals can find — kept apart.",
  CONFLICT:
    "The observations contradict one another. Kept separate; human review raised. Reconciliation does not resolve the conflict.",
  UNCERTAIN: "The signals do not resolve the question — kept separate by default.",
});

function Heading() {
  return (
    <div className="view-heading">
      <h1 className="view-heading__title">Observation Reconciliation / Separation</h1>
      <p className="view-heading__sub">
        Deterministic case partitioning across independent signal families.
        Upholds <strong>CORRELATION ≠ IDENTITY</strong>: separation is preserved
        whenever a shared root cause cannot be deterministically proved. A{" "}
        <strong>RELATED</strong> link is a deterministic relationship, not
        physical proof — physics validation is a separate authority.
      </p>
    </div>
  );
}

function Banner({ tone, title, children }) {
  return (
    <div className={`recon-banner recon-banner--${tone}`} role="status">
      <div className="recon-banner__title">
        <StatusBadge
          status={
            tone === "crit"
              ? "CRITICAL"
              : tone === "warn"
              ? "WARNING"
              : tone === "ok"
              ? "OK"
              : "INFO"
          }
          label={title}
        />
      </div>
      {children ? <p className="recon-banner__body">{children}</p> : null}
    </div>
  );
}

const caseColumns = [
  { key: "case_id", label: "Case ID" },
  {
    key: "subsystems",
    label: "Subsystems",
    render: (c) =>
      Array.isArray(c.subsystems) ? c.subsystems.join(", ") : c.subsystems || "—",
  },
  {
    key: "channels",
    label: "Channels",
    render: (c) =>
      Array.isArray(c.channels) ? c.channels.join(", ") : c.channels || "—",
  },
  {
    key: "window",
    label: "Onset window",
    render: (c) =>
      c.window_start_s != null
        ? `T${c.window_start_s >= 0 ? "+" : ""}${Number(c.window_start_s).toFixed(1)}s`
        : "—",
  },
  {
    key: "event_ids",
    label: "Member events",
    render: (c) => (Array.isArray(c.event_ids) ? c.event_ids.length : 1),
  },
];

const relColumns = [
  {
    key: "pair",
    label: "Cases",
    render: (r) => (
      <span className="mono fs-sm">
        {r.source_case_id} ↔ {r.target_case_id}
      </span>
    ),
  },
  {
    key: "relationship_type",
    label: "Type",
    render: (r) => (
      <StatusBadge status={r.relationship_type} title={REL_HELP[r.relationship_type]} />
    ),
  },
  {
    key: "merge_permitted",
    label: "Merge",
    render: (r) => (r.merge_permitted ? "PERMITTED" : "NOT PERMITTED"),
  },
  {
    key: "basis",
    label: "Deterministic basis",
    render: (r) =>
      Array.isArray(r.deterministic_reasons) && r.deterministic_reasons.length
        ? r.deterministic_reasons.join(" ")
        : "—",
  },
  {
    key: "physics",
    label: "Physics",
    render: (r) =>
      Array.isArray(r.physics_support) && r.physics_support.length ? (
        <StatusBadge status="VALIDATED" label="SUPPORTED" />
      ) : r.relationship_type === "RELATED" ? (
        <StatusBadge status="PENDING" label="PENDING" />
      ) : (
        "N/A"
      ),
  },
];

export default function ReconciliationView() {
  const { reconciliation, selectedScenario } = useSentinel();
  const entity = reconciliation || { data: null, loading: false, error: null };
  const data = entity.data;

  // ── State F: backend error ──────────────────────────────────────────────
  if (entity.error) {
    return (
      <div className="view-stack">
        <Heading />
        <Panel id="recon-error" title="Reconciliation">
          <div className="async-state async-state--error" role="alert">
            <strong>BACKEND ERROR</strong>
            <span>{entity.error}</span>
          </div>
        </Panel>
      </div>
    );
  }

  // ── loading ───────────────────────────────────────────────────────────────
  if (entity.loading) {
    return (
      <div className="view-stack">
        <Heading />
        <Panel id="recon-loading" title="Reconciliation">
          <div className="async-state" role="status">
            <span className="async-state__spinner" aria-hidden="true" />
            <span>RECONCILING OBSERVATIONS…</span>
          </div>
        </Panel>
      </div>
    );
  }

  // ── State B: not run (no scenario / no data) ───────────────────────────────
  if (!data) {
    return (
      <div className="view-stack">
        <Heading />
        <Panel id="recon-idle" title="Reconciliation">
          <p className="muted-text">
            {selectedScenario
              ? "No reconciliation result yet."
              : "Select a scenario to run deterministic reconciliation."}
          </p>
        </Panel>
      </div>
    );
  }

  // ── State A: disabled (feature flag off) ───────────────────────────────────
  if (data.reconciliation_enabled === false) {
    return (
      <div className="view-stack">
        <Heading />
        <Banner tone="info" title="RECONCILIATION DISABLED">
          The reconciliation engine is off by default. This is a feature-gated
          capability, not an error — the empty result below means “disabled”,
          not “nothing found”. To enable it for the demo, start the backend with{" "}
          <code>RECONCILIATION_ENABLED=true</code> (flag{" "}
          <code>{data.flag_name || "RECONCILIATION_ENABLED"}</code>), then
          reselect the scenario.
        </Banner>
        <Panel id="recon-disabled" title="Reconciliation">
          <p className="muted-text">
            Engine version {data.engine_version || "N/A"} · config{" "}
            {data.config_version || "N/A"}. Reconciliation performs deterministic
            case separation only; it never calls an LLM, authorizes commands, or
            overrides physics or safety.
          </p>
        </Panel>
      </div>
    );
  }

  // ── Executed (states C / D / E) ────────────────────────────────────────────
  const cases = data.cases || [];
  const relationships = data.relationships || [];
  const totalCases = data.total_cases ?? cases.length;
  const isolatedCases = data.isolated_cases ?? 0;
  const relatedCount = data.related_relationships ?? 0;
  const conflictCount = data.conflicts_detected ?? 0;
  const humanReview = Boolean(data.human_review_required);

  let banner;
  if (conflictCount > 0) {
    banner = (
      <Banner tone="crit" title={`CONFLICT DETECTED (${conflictCount})`}>
        Contradictory observations were found. The cases are kept separate and
        human review is required — reconciliation does not resolve the conflict.
      </Banner>
    );
  } else if (humanReview) {
    banner = (
      <Banner tone="warn" title="HUMAN REVIEW REQUIRED">
        The reconciliation layer raised the review gate for this scenario.
      </Banner>
    );
  } else if (totalCases === 0) {
    banner = (
      <Banner tone="info" title="NO OBSERVATIONS TO RECONCILE">
        The engine ran and found no anomalous observations to separate for this
        scenario. This is an executed result, distinct from “disabled”.
      </Banner>
    );
  } else if (totalCases === 1 || relatedCount === 0) {
    banner = (
      <Banner tone="ok" title="SEPARATION UPHELD">
        {totalCases === 1
          ? "A single isolated fault case — no cross-case relationships to establish."
          : `${totalCases} cases kept separate; no deterministic cross-case relationship found.`}
      </Banner>
    );
  } else {
    banner = (
      <Banner tone="ok" title="CASES SEPARATED">
        {`${totalCases} deterministic cases · ${relatedCount} related (physics validation pending). Merges are permitted only for DUPLICATE / SAME_CASE.`}
      </Banner>
    );
  }

  return (
    <div className="view-stack">
      <Heading />

      {banner}

      <div className="grid-4">
        <Panel id="recon-cases" title="Cases">
          <div className="stat-number">{totalCases}</div>
          <p className="muted-text fs-sm">{isolatedCases} isolated · disjoint fault scopes</p>
        </Panel>

        <Panel id="recon-rel" title="Related">
          <div className="stat-number">{relatedCount}</div>
          <StatusBadge status="RELATED" />
          <p className="muted-text fs-sm">Deterministic links · physics pending</p>
        </Panel>

        <Panel id="recon-conflicts" title="Conflicts">
          <div className="stat-number">{conflictCount}</div>
          <StatusBadge status={conflictCount > 0 ? "CONFLICT" : "NOMINAL"} />
          <p className="muted-text fs-sm">Contradictions preserved for review</p>
        </Panel>

        <Panel id="recon-review" title="Review authority">
          <div className="stat-number" style={{ fontSize: "1.2rem", marginTop: "0.5rem" }}>
            {humanReview ? "HUMAN REVIEW" : "AUTOMATED"}
          </div>
          <StatusBadge status={humanReview ? "CRITICAL" : "OK"} />
          <p className="muted-text fs-sm">Monotone review-requirement gate</p>
        </Panel>
      </div>

      <Panel
        id="recon-case-list"
        title="Reconciled cases"
        actions={
          <span className="mono fs-sm muted-text">
            scenario {String(data.scenario_id ?? "—")} · engine {data.engine_version || "N/A"}
          </span>
        }
      >
        {cases.length === 0 ? (
          <p className="muted-text">
            The engine ran and produced no cases — there were no anomalous
            observations to reconcile for this scenario.
          </p>
        ) : (
          <DataTable
            caption="Deterministically isolated fault cases"
            columns={caseColumns}
            rows={cases.map((c) => ({ ...c, key: c.case_id }))}
          />
        )}
      </Panel>

      <Panel id="recon-rel-list" title="Case relationships & propagation graph">
        {relationships.length === 0 ? (
          <p className="muted-text">
            No cross-case relationships — a single case, or nothing to relate.
          </p>
        ) : (
          <DataTable
            caption="Inter-case relationships with deterministic basis"
            columns={relColumns}
            rows={relationships.map((r) => ({ ...r, key: r.relationship_id }))}
          />
        )}
      </Panel>

      {data.authority_note ? (
        <p className="muted-text fs-sm">{data.authority_note}</p>
      ) : null}
    </div>
  );
}
